import numpy as np


def rnn_linear(x, w, u, h0):
    h, out = h0, []
    for xt in x:
        h = w * h + u * xt
        out.append(h)
    return np.array(out)


def rnn_tanh(x, w, u, b, h0):
    h, out = h0, []
    for xt in x:
        h = np.tanh(w * h + u * xt + b)
        out.append(h)
    return np.array(out)

