import numpy as np


def simulate_ar1(phi, n, seed):
    e = np.random.default_rng(seed).standard_normal(n)
    x = np.empty(n)
    x[0] = e[0]
    for t in range(1, n):
        x[t] = phi * x[t - 1] + e[t]
    return x


def shocks(n, seed):
    return np.random.default_rng(seed).standard_normal(n)

